<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { Leaf } from 'lucide-vue-next';import { useAppStore } from '../store'
const store=useAppStore(),router=useRouter(),username=ref(''),password=ref(''),registering=ref(false),busy=ref(false)
async function submit(){busy.value=true;try{registering.value?await store.register(username.value,password.value):await store.login(username.value,password.value);await router.replace('/chat')}catch{}finally{busy.value=false}}
</script>
<template><main class="auth-page"><form class="auth-card" @submit.prevent="submit"><div class="brand"><Leaf :size="26"/><span>Learning Q&A</span></div><h1>{{registering?'创建账号':'欢迎回来'}}</h1><p>登录后，你的会话、资料与长期记忆都只属于当前账号。</p><label>用户名<input v-model="username" autocomplete="username" minlength="3" maxlength="32" required></label><label>密码<input v-model="password" type="password" :autocomplete="registering?'new-password':'current-password'" minlength="6" maxlength="30" required></label><button class="primary" :disabled="busy">{{busy?'请稍候':registering?'注册并登录':'登录'}}</button><button type="button" class="ghost" @click="registering=!registering">{{registering?'已有账号？返回登录':'没有账号？注册'}}</button><div v-if="store.error" class="stream-error" role="alert">{{store.error}}</div></form></main></template>